// Keep historical inline ABIs for old deployments and select the corresponding
// fragments from the generated contract ABI for the wallet-ID deployment.
// Resolve on construction: tests and deployment profiles can change the schema.
import { Interface } from 'ethers';
import { hasWalletIds } from '../chain/schema.js';

const cache = new WeakMap();
export function walletAbi(legacy, canonical) {
  if (!hasWalletIds()) return legacy;
  let byCanonical = cache.get(legacy);
  if (!byCanonical) { byCanonical = new WeakMap(); cache.set(legacy, byCanonical); }
  if (byCanonical.has(canonical)) return byCanonical.get(canonical);
  const old = new Interface(legacy);
  const current = new Interface(canonical);
  const signature = fragment => fragment.inputs.map(input => input.type).join(',');
  const selected = old.fragments.flatMap(fragment => {
    const name = fragment.name === 'previewSalvageFlipBacking' ? 'previewFlipBacking' : fragment.name;
    const candidates = current.fragments.filter(item => item.type === fragment.type && item.name === name);
    if (!candidates.length) return fragment.type === 'error' ? [fragment] : [];
    const sig = signature(fragment);
    const match = candidates.find(item => signature(item) === sig)
      ?? candidates.find(item => signature(item) === sig.replaceAll('address', 'uint32'))
      ?? (candidates.length === 1 ? candidates[0] : null);
    if (!match) throw new Error(`Ambiguous wallet-ID ABI migration: ${fragment.format()}`);
    return [match];
  });
  byCanonical.set(canonical, selected);
  return selected;
}
